export type IWuKongFacade = {

	-- 获取根容器（用户容器）
	GetRootContainer: (self: IWuKongFacade) -> IUserContainer?,

	-- 设置根容器
	-- @param root 用户容器实例
	-- @param disableAutoStart 是否禁用自动启动，默认为false
	SetRoot: (self: IWuKongFacade, root: IUserContainer, disableAutoStart: boolean?) -> (),

	-- 获取用户编号
	GetUserId: (self: IWuKongFacade) -> number,

	-- 执行查询操作
	-- @param location 查询位置
	-- @param ... 查询参数
	-- @return 查询结果
	ExecuteQuery: (self: IWuKongFacade, location: string, ...any) -> any,

	-- 执行行动操作
	-- @param location 行动位置
	-- @param ... 行动参数
	-- @return 行动结果
	ExecuteAction: (self: IWuKongFacade, location: string, ...any) -> any,

	-- 执行验证操作
	-- @param location 验证位置
	-- @param ... 验证参数
	-- @return 验证结果
	ExecuteValidate: (self: IWuKongFacade, location: string, ...any) -> any,

	-- 根据路径获取指定子节点
	-- @param location 节点路径
	-- @return 子节点容器
	GetChild: (self: IWuKongFacade, location: string) -> IContainer,

	-- 尝试获取指定子节点
	-- @param location 节点路径
	-- @return (是否成功, 子节点容器)
	TryGetChild: (self: IWuKongFacade, location: string) -> (boolean, IContainer?),

	-- 执行命令（仅供命令行调用）
	-- @param commandId 命令ID
	-- @param ... 输入参数
	ExecuteCommand: (self: IWuKongFacade, commandId: string, ...string) -> (),

	-- 获取所有命令ID列表
	-- @return 命令ID数组
	GetCommandIds: (self: IWuKongFacade) -> { string },

	-- 获取当前Unix时间戳
	-- @return Unix时间戳
	GetUnixTime: (self: IWuKongFacade) -> number,

	-- 注册格子观察者（不可取消，除非调用Dispose）
	-- @param slotPath 格子路径
	-- @param handler 处理函数
	RegisterSlotObserver: (self: IWuKongFacade, slotPath: string, handler: (ISlot, string) -> ()) -> (),

	-- 注册执行行动观察者（不可取消，除非调用Dispose）
	-- @param handler 处理函数
	RegisterActionObserver: (self: IWuKongFacade, handler: (string, any, any, any, any, any) -> ()) -> (),
}
